3	/**
4	 * Derives an owner's locality (region) from its postcode and city.
5	 *
6	 * <p>The postcode takes precedence: the region is resolved from the postcode range first
7	 * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only when the postcode is absent or falls in
8	 * no known range does derivation fall back to the fixed city-to-region table. This returns the same
9	 * region for the pinned cities but disambiguates cities that share a name.
10	 *
11	 * <p>Kept as a standalone helper (rather than a mapper method) so MapStruct does not adopt it
12	 * as an implicit {@code String -> String} mapping method for unrelated owner string properties.
13	 */
14	public final class OwnerLocality {
15	
16	    private OwnerLocality() {
17	    }
18	
19	    /**
20	     * Derives an owner's canonical region, preferring the postcode over the city. The region is
21	     * resolved from the postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); when the
22	     * postcode is {@code null} or lies in no known range, derivation falls back to the city-to-region
23	     * table via {@link #of(String)}.
24	     *
25	     * @param city the owner's city (may be {@code null})
26	     * @param postcode the owner's postcode (may be {@code null})
27	     * @return the canonical region string, or {@code "UNKNOWN"} when neither the postcode nor the
28	     *         city resolves to a known region
29	     */
30	    public static String of(String city, String postcode) {
31	        String byPostcode = fromPostcode(postcode);
32	        return byPostcode != null ? byPostcode : of(city);
33	    }
34	
35	    /**
36	     * Maps a city to its canonical region: Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD.
37	     *
38	     * @param city the owner's city (may be {@code null})
39	     * @return the canonical region string, or {@code "UNKNOWN"} when the city is not in the table
40	     */
41	    public static String of(String city) {
42	        if (city == null) {
43	            return "UNKNOWN";
44	        }
45	        return switch (city) {
46	            case "Sydney" -> "NSW";
47	            case "Melbourne" -> "VIC";
48	            case "Brisbane" -> "QLD";
49	            default -> "UNKNOWN";
50	        };
51	    }
52	
53	    /**
54	     * Derives an owner's IANA timezone from its locality (region), preferring the postcode over the
55	     * city, via the fixed region-to-timezone table: NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
56	     * QLD-&gt;Australia/Brisbane. The region is resolved with {@link #of(String, String)}.
57	     *
58	     * @param city the owner's city (may be {@code null})
59	     * @param postcode the owner's postcode (may be {@code null})
60	     * @return the IANA timezone name, or {@code null} when the region is not in the table
61	     */
62	    public static String timezoneOf(String city, String postcode) {
63	        return timezoneOfRegion(of(city, postcode));
64	    }
65	
66	    /**
67	     * Maps a canonical region to its IANA timezone: NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
68	     * QLD-&gt;Australia/Brisbane.
69	     *
70	     * @param region the canonical region string (may be {@code null})
71	     * @return the IANA timezone name, or {@code null} when the region is not in the table
72	     */
73	    public static String timezoneOfRegion(String region) {
74	        if (region == null) {
75	            return null;
76	        }
77	        return switch (region) {
78	            case "NSW" -> "Australia/Sydney";
79	            case "VIC" -> "Australia/Melbourne";
80	            case "QLD" -> "Australia/Brisbane";
81	            default -> null;
82	        };
83	    }
84	
85	    /**
86	     * Resolves a region from a postcode range: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
87	     *
88	     * @param postcode the owner's postcode (may be {@code null})
89	     * @return the region string, or {@code null} when the postcode is absent, not a 4-digit value, or
90	     *         falls in no known range
91	     */
92	    private static String fromPostcode(String postcode) {
93	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
94	            return null;
95	        }
96	        int value = Integer.parseInt(postcode);
97	        if (value >= 2000 && value <= 2099) {
98	            return "NSW";
99	        }
100	        if (value >= 3000 && value <= 3099) {
101	            return "VIC";
102	        }
103	        if (value >= 4000 && value <= 4099) {
104	            return "QLD";
105	        }
106	        return null;
107	    }
108	}
