1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.security.MessageDigest;
14	import java.security.NoSuchAlgorithmException;
15	import java.time.LocalDate;
16	import java.time.Period;
17	import java.util.Collection;
18	import java.util.List;
19	import java.util.Locale;
20	
21	/**
22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public abstract class OwnerMapper {
26	
27	    /**
28	     * Points added when the owner has an email address.
29	     */
30	    private static final int EMAIL_POINTS = 2;
31	
32	    /**
33	     * Points added when the owner has no namesakes ({@code namesakeCount} is 0).
34	     */
35	    private static final int NO_NAMESAKE_POINTS = 1;
36	
37	    /**
38	     * Points added when the owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more members.
39	     */
40	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
41	
42	    /**
43	     * The household size (members, including the owner) at which the large-household points are awarded.
44	     */
45	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
46	
47	    /**
48	     * Points added when the owner's tenure reaches {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal year(s).
49	     */
50	    private static final int TENURE_POINTS = 3;
51	
52	    /**
53	     * Tenure, in elapsed fiscal years, that an owner must reach to earn the tenure points.
54	     */
55	    private static final int TENURE_POINTS_FISCAL_YEARS = 1;
56	
57	    /**
58	     * The month (1 July) on which the fiscal year starts.
59	     */
60	    private static final int FISCAL_YEAR_START_MONTH = 7;
61	
62	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
63	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
64	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
65	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
66	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
67	    @Mapping(target = "membershipLevel", expression = "java(owner.getMembershipLevel() != null ? owner.getMembershipLevel() : membershipLevel(owner))")
68	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.mapper.OwnerLocality.of(owner.getCity(), owner.getPostcode()))")
69	    @Mapping(target = "timezone", expression = "java(org.springframework.samples.petclinic.mapper.OwnerLocality.timezoneOf(owner.getCity(), owner.getPostcode()))")
70	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
71	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
72	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
73	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
74	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
75	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
76	    @Mapping(target = "riskFlag", expression = "java(riskFlag(owner))")
77	    public abstract OwnerDto toOwnerDto(Owner owner);
78	
79	    public abstract Owner toOwner(OwnerDto ownerDto);
80	
81	    @Mapping(target = "id", ignore = true)
82	    @Mapping(target = "pets", ignore = true)
83	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
84	
85	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
86	
87	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
88	
89	    /**
90	     * Computes an owner's membership points. Points start at 0 and accumulate: {@value #EMAIL_POINTS} when an
91	     * email is present, {@value #NO_NAMESAKE_POINTS} when {@code namesakeCount} is 0,
92	     * {@value #LARGE_HOUSEHOLD_POINTS} for a household of {@value #LARGE_HOUSEHOLD_SIZE} or more members, and
93	     * {@value #TENURE_POINTS} for a tenure of at least {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal
94	     * year(s) (measured from {@code registrationDate}). Because a newly created owner has zero elapsed fiscal
95	     * years, a new owner never earns the tenure points.
96	     *
97	     * @param owner the owner whose points are being computed
98	     * @return the owner's membership points (0 or more)
99	     */
100	    protected Integer membershipPoints(Owner owner) {
101	        return membershipPoints(owner, owner.getHouseholdSize());
102	    }
103	
104	    /**
105	     * Computes an owner's membership points as {@link #membershipPoints(Owner)} does, but using the supplied
106	     * {@code householdSize} in place of the owner's stored one when awarding the large-household points. This
107	     * lets a caller evaluate an owner's points against the household's <em>current</em> size (for example when
108	     * computing the new-owner level ceiling) without mutating the owner.
109	     *
110	     * @param owner the owner whose points are being computed
111	     * @param householdSize the household size to measure the large-household points against
112	     * @return the owner's membership points (0 or more) for the given household size
113	     */
114	    protected Integer membershipPoints(Owner owner, Integer householdSize) {
115	        int points = 0;
116	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
117	            points += EMAIL_POINTS;
118	        }
119	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
120	            points += NO_NAMESAKE_POINTS;
121	        }
122	        if (householdSize != null && householdSize >= LARGE_HOUSEHOLD_SIZE) {
123	            points += LARGE_HOUSEHOLD_POINTS;
124	        }
125	        if (tenureFiscalYears(owner) >= TENURE_POINTS_FISCAL_YEARS) {
126	            points += TENURE_POINTS;
127	        }
128	        return points;
129	    }
130	
131	    /**
132	     * Maps an owner's membership points to a numeric membership level: level 1 for 0-1 points, level 2 for
133	     * 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more points.
134	     *
135	     * @param owner the owner whose level is being computed
136	     * @return the membership level (between 1 and 4 inclusive)
137	     */
138	    protected Integer membershipLevel(Owner owner) {
139	        return levelForPoints(membershipPoints(owner));
140	    }
141	
142	    /**
143	     * Computes an owner's membership level as {@link #membershipLevel(Owner)} does, but measuring the
144	     * large-household points against the supplied {@code householdSize} rather than the owner's stored one.
145	     * This is the uncapped level an owner would report were the household of the given size; it is the value
146	     * the create endpoint compares between household members when computing a new owner's level ceiling.
147	     *
148	     * @param owner the owner whose level is being computed
149	     * @param householdSize the household size to measure the large-household points against
150	     * @return the membership level (between 1 and 4 inclusive) for the given household size
151	     */
152	    public Integer membershipLevelForHouseholdSize(Owner owner, Integer householdSize) {
153	        return levelForPoints(membershipPoints(owner, householdSize));
154	    }
155	
156	    /**
157	     * Maps membership points to a numeric membership level: level 1 for 0-1 points, level 2 for 2-3 points,
158	     * level 3 for 4-5 points, and level 4 for 6 or more points.
159	     *
160	     * @param points the membership points to map
161	     * @return the membership level (between 1 and 4 inclusive)
162	     */
163	    private Integer levelForPoints(int points) {
164	        if (points >= 6) {
165	            return 4;
166	        }
167	        if (points >= 4) {
168	            return 3;
169	        }
170	        if (points >= 2) {
171	            return 2;
172	        }
173	        return 1;
174	    }
175	
176	    /**
177	     * Computes an owner's tenure as the number of elapsed fiscal years between {@code registrationDate} and
178	     * today: the difference between the fiscal year (starting 1 July) of today and that of the registration
179	     * date. A newly created owner (registered in the current fiscal year) has zero tenure. Owners with no
180	     * {@code registrationDate}, or a registration date in a later fiscal year, are treated as zero tenure.
181	     *
182	     * @param owner the owner whose tenure is being computed
183	     * @return the owner's tenure in elapsed fiscal years, never negative
184	     */
185	    protected long tenureFiscalYears(Owner owner) {
186	        LocalDate registrationDate = owner.getRegistrationDate();
187	        if (registrationDate == null) {
188	            return 0;
189	        }
190	        long years = (long) fiscalYearStart(LocalDate.now()) - fiscalYearStart(registrationDate);
191	        return Math.max(years, 0);
192	    }
193	
194	    /**
195	     * Derives an owner's {@code fiscalYear}, formatted {@code 'FY<YY>'}, from the (already
196	     * business-day-adjusted) {@code registrationDate}. The fiscal year starts on 1 July and is labelled by
197	     * the calendar year in which it starts, so a registration on or after 1 July belongs to that year's
198	     * fiscal year and an earlier one to the previous year's (e.g. {@code 2026-08-15} yields {@code 'FY26'}).
199	     *
200	     * @param owner the owner whose fiscal year is being derived
201	     * @return the owner's fiscal year as {@code 'FY<YY>'}
202	     */
203	    protected String fiscalYear(Owner owner) {
204	        return "FY" + fiscalYearSuffix(owner.getRegistrationDate());
205	    }
206	
207	    /**
208	     * Returns the two-digit fiscal-year suffix ({@code '<YY>'}) for the given date: the last two digits of
209	     * the calendar year in which that date's fiscal year (starting 1 July) begins. This is the shared segment
210	     * used by both {@link #fiscalYear(Owner)} and the membership number.
211	     *
212	     * @param date the date whose fiscal-year suffix is computed
213	     * @return the zero-padded two-digit fiscal-year suffix
214	     */
215	    protected String fiscalYearSuffix(LocalDate date) {
216	        return String.format("%02d", fiscalYearStart(date) % 100);
217	    }
218	
219	    /**
220	     * Returns the calendar year in which the fiscal year containing {@code date} starts. The fiscal year
221	     * starts on 1 July, so dates from July onward start their fiscal year in the same calendar year, while
222	     * dates from January to June belong to the fiscal year that started in the previous calendar year.
223	     *
224	     * @param date the date whose fiscal-year start is computed
225	     * @return the calendar year in which the containing fiscal year starts
226	     */
227	    protected int fiscalYearStart(LocalDate date) {
228	        int year = date.getYear();
229	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? year : year - 1;
230	    }
231	
232	    /**
233	     * Derives an owner's preferred contact channel at read time: {@code 'EMAIL'} when an email address is
234	     * present, otherwise {@code 'PHONE'}.
235	     *
236	     * @param owner the owner whose contact preference is being computed
237	     * @return {@code 'EMAIL'} when the owner has a non-blank email, otherwise {@code 'PHONE'}
238	     */
239	    protected String contactPreference(Owner owner) {
240	        return (owner.getEmail() != null && !owner.getEmail().isBlank()) ? "EMAIL" : "PHONE";
241	    }
242	
243	    /**
244	     * Derives an owner's age band from {@code birthDate}, measured against {@code registrationDate}: the
245	     * completed years between the two dates place the owner in {@code 'MINOR'} (under 18), {@code 'ADULT'}
246	     * (18 to 64 inclusive) or {@code 'SENIOR'} (65 or over). Returns {@code null} when the owner has no
247	     * {@code birthDate}, so the field is simply absent for owners created without one.
248	     *
249	     * @param owner the owner whose age band is being derived
250	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when no birth date is set
251	     */
252	    protected String ageBand(Owner owner) {
253	        if (owner.getBirthDate() == null) {
254	            return null;
255	        }
256	        LocalDate reference = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
257	        int years = Period.between(owner.getBirthDate(), reference).getYears();
258	        if (years < 18) {
259	            return "MINOR";
260	        }
261	        if (years < 65) {
262	            return "ADULT";
263	        }
264	        return "SENIOR";
265	    }
266	
267	    /**
268	     * Derives an owner's {@code identityKey}: the lower-case hex SHA-256 digest of the normalized telephone,
269	     * the lower-cased email (or an empty string when absent) and the {@link #soundex(String) soundex} of the
270	     * last name, joined by {@code '|'} in that order before hashing. This is the single 64-hex key used for
271	     * duplicate detection, so the value returned here matches the one the create endpoint compares.
272	     *
273	     * @param owner the owner whose identity key is being derived
274	     * @return the owner's identity key, a 64-character lower-case hex SHA-256 digest
275	     */
276	    protected String identityKey(Owner owner) {
277	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
278	        String email = owner.getEmail() == null ? "" : owner.getEmail();
279	        String soundex = soundex(owner.getLastName());
280	        return sha256Hex(telephone + "|" + email + "|" + soundex);
281	    }
282	
283	    /**
284	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
285	     *
286	     * @param value the value to hash
287	     * @return the 64-character lower-case hex SHA-256 digest
288	     */
289	    private String sha256Hex(String value) {
290	        try {
291	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
292	            StringBuilder sb = new StringBuilder(digest.length * 2);
293	            for (byte b : digest) {
294	                sb.append(String.format("%02x", b));
295	            }
296	            return sb.toString();
297	        }
298	        catch (NoSuchAlgorithmException e) {
299	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
300	        }
301	    }
302	
303	    /**
304	     * Computes the American Soundex code of the given value: the retained (upper-cased) first letter
305	     * followed by three digits derived from the remaining consonants, right-padded with zeros or truncated
306	     * to length four. Non-letters are ignored; adjacent letters mapping to the same digit are coded once
307	     * (bridged across {@code 'H'}/{@code 'W'}), and vowels reset the run. A {@code null} or letter-free
308	     * value yields an empty string. This matches the create endpoint's soundex so identity keys agree.
309	     *
310	     * @param value the value (typically a last name) to encode
311	     * @return the four-character Soundex code, or an empty string when there are no letters
312	     */
313	    private String soundex(String value) {
314	        if (value == null) {
315	            return "";
316	        }
317	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
318	        if (letters.isEmpty()) {
319	            return "";
320	        }
321	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
322	        char prev = soundexDigit(letters.charAt(0));
323	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
324	            char c = letters.charAt(i);
325	            if (c == 'H' || c == 'W') {
326	                continue;
327	            }
328	            char digit = soundexDigit(c);
329	            if (digit != '0' && digit != prev) {
330	                code.append(digit);
331	            }
332	            prev = digit;
333	        }
334	        while (code.length() < 4) {
335	            code.append('0');
336	        }
337	        return code.toString();
338	    }
339	
340	    private char soundexDigit(char c) {
341	        return switch (c) {
342	            case 'B', 'F', 'P', 'V' -> '1';
343	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
344	            case 'D', 'T' -> '3';
345	            case 'L' -> '4';
346	            case 'M', 'N' -> '5';
347	            case 'R' -> '6';
348	            default -> '0';
349	        };
350	    }
351	
352	    /**
353	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
354	     * national digits grouped in threes from the left (e.g. {@code '+61412345678'} becomes
355	     * {@code '+61 412 345 678'}). The raw {@code telephone} is left untouched in E.164 form. Values that are
356	     * {@code null} or not in E.164 form (no leading {@code '+'}) are returned unchanged.
357	     * <p>
358	     * The country code is split off using the codes the application recognises: {@code '+1'} (NANP) is a
359	     * single digit and any other number is assumed to carry the default {@code '+61'}-style two-digit code.
360	     *
361	     * @param owner the owner whose telephone is being formatted
362	     * @return the human-formatted telephone, or the raw value when it is {@code null} or not E.164
363	     */
364	    protected String telephoneDisplay(Owner owner) {
365	        String telephone = owner.getTelephone();
366	        if (telephone == null || !telephone.startsWith("+")) {
367	            return telephone;
368	        }
369	        String digits = telephone.substring(1);
370	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
371	        if (digits.length() <= countryCodeLength) {
372	            return telephone;
373	        }
374	        String countryCode = digits.substring(0, countryCodeLength);
375	        String national = digits.substring(countryCodeLength);
376	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
377	        for (int i = 0; i < national.length(); i++) {
378	            if (i % 3 == 0) {
379	                grouped.append(' ');
380	            }
381	            grouped.append(national.charAt(i));
382	        }
383	        return grouped.toString();
384	    }
385	
386	    /**
387	     * Composes the owner's salutation: the {@code title}, a single space and the last name (e.g.
388	     * {@code 'DR Franklin'}) when a non-blank {@code title} was supplied, or just the last name when no
389	     * title was given.
390	     *
391	     * @param owner the owner whose salutation is being composed
392	     * @return {@code '<title> <lastName>'} when a title is present, otherwise the last name alone
393	     */
394	    protected String salutation(Owner owner) {
395	        String title = owner.getTitle();
396	        if (title == null || title.isBlank()) {
397	            return owner.getLastName();
398	        }
399	        return title + " " + owner.getLastName();
400	    }
401	
402	    /**
403	     * Derives an owner's {@code selfLink}: the canonical relative URL of the owner resource, formatted
404	     * {@code '/api/owners/<id>'} from the owner's id. Returns {@code null} when the owner has no id yet.
405	     *
406	     * @param owner the owner whose self link is being derived
407	     * @return the owner's self link, or {@code null} when the owner has no id
408	     */
409	    protected String selfLink(Owner owner) {
410	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
411	    }
412	
413	    /**
414	     * Derives an owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
415	     * {@code 'PREMIUM'} when the owner's effective membership level is 3 or more, otherwise
416	     * {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's locality is a known region (NSW,
417	     * VIC or QLD), otherwise {@code 'REGIONAL'}. The result is one of {@code 'PREMIUM_METRO'},
418	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}.
419	     *
420	     * @param owner the owner whose segment is being derived
421	     * @return the owner's segment as {@code '<TIER>_<AREA>'}
422	     */
423	    protected String ownerSegment(Owner owner) {
424	        Integer level = owner.getMembershipLevel() != null ? owner.getMembershipLevel() : membershipLevel(owner);
425	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
426	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
427	        boolean known = "NSW".equals(region) || "VIC".equals(region) || "QLD".equals(region);
428	        String area = known ? "METRO" : "REGIONAL";
429	        return tier + "_" + area;
430	    }
431	
432	    /**
433	     * The second-level labels of the known disposable email providers (the exact-match blocklist is
434	     * {@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). A domain that carries one of
435	     * these labels but is not itself on the exact blocklist is treated as <em>disposable-adjacent</em>.
436	     */
437	    private static final java.util.Set<String> DISPOSABLE_PROVIDER_LABELS =
438	        java.util.Set.of("mailinator", "tempmail", "guerrillamail");
439	
440	    /**
441	     * Derives an owner's {@code riskFlag}: {@code true} when the owner warrants a manual risk review, i.e.
442	     * when any of the following hold, otherwise {@code false}:
443	     * <ul>
444	     *   <li>the owner is a possible duplicate ({@code possibleDuplicate} is {@code true});</li>
445	     *   <li>the owner's email domain is {@link #disposableAdjacent(String) disposable-adjacent};</li>
446	     *   <li>the owner's city is over its soft capacity ({@code capacityWarning} is {@code true}).</li>
447	     * </ul>
448	     *
449	     * @param owner the owner whose risk flag is being derived
450	     * @return {@code true} when any risk condition holds, otherwise {@code false}
451	     */
452	    protected Boolean riskFlag(Owner owner) {
453	        boolean possibleDuplicate = Boolean.TRUE.equals(owner.getPossibleDuplicate());
454	        boolean overSoftCapacity = Boolean.TRUE.equals(owner.getCapacityWarning());
455	        return possibleDuplicate || overSoftCapacity || disposableAdjacent(owner.getEmail());
456	    }
457	
458	    /**
459	     * Reports whether an email address is <em>disposable-adjacent</em>: its domain carries a known disposable
460	     * provider's name (see {@link #DISPOSABLE_PROVIDER_LABELS}) as one of its dot-separated labels, without
461	     * being an exact blocklisted domain (those are rejected at creation and never stored). So
462	     * {@code x@mailinator.net} and {@code x@sub.mailinator.com} are disposable-adjacent, while a plain domain
463	     * such as {@code x@example.test} is not. A {@code null} or blank email is never disposable-adjacent.
464	     *
465	     * @param email the owner's stored (already normalized) email, or {@code null} when absent
466	     * @return {@code true} when the email's domain carries a disposable provider label, otherwise {@code false}
467	     */
468	    protected boolean disposableAdjacent(String email) {
469	        if (email == null || email.isBlank()) {
470	            return false;
471	        }
472	        int at = email.lastIndexOf('@');
473	        if (at < 0) {
474	            return false;
475	        }
476	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
477	        for (String label : domain.split("\\.")) {
478	            if (DISPOSABLE_PROVIDER_LABELS.contains(label)) {
479	                return true;
480	            }
481	        }
482	        return false;
483	    }
484	
485	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
486	        OwnerPageDto ownerPageDto = new OwnerPageDto();
487	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
488	        ownerPageDto.setPage(ownerPage.getNumber());
489	        ownerPageDto.setSize(ownerPage.getSize());
490	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
491	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
492	        return ownerPageDto;
493	    }
494	}
