184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
187	        String idempotencyKey = idempotencyKey();
188	        if (idempotencyKey != null) {
189	            Integer existingId = IDEMPOTENT_CREATES.get(idempotencyKey);
190	            if (existingId != null) {
191	                Owner existing = this.clinicService.findOwnerById(existingId);
192	                if (existing != null) {
193	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
194	                }
195	            }
196	        }
197	        rejectMissingOrBlankFields(ownerFieldsDto);
198	        HttpHeaders headers = new HttpHeaders();
199	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
200	        applyAddress(owner);
201	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
202	        owner.setEmail(normalizeEmail(owner.getEmail()));
203	        validatePostcode(owner.getPostcode(), owner.getCity());
204	        rejectFutureRegistrationDate(owner.getRegistrationDate());
205	        if (owner.getRegistrationDate() == null) {
206	            owner.setRegistrationDate(LocalDate.now());
207	        }
208	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
209	        rejectDailyLimitReached(owner.getRegistrationDate());
210	        rejectCityAtCapacity(owner.getCity());
211	        owner.setHouseholdId(computeHouseholdId(owner));
212	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
213	        rejectDuplicateIdentity(owner);
214	        assignPossibleDuplicate(owner, sharesHousehold);
215	        owner.setMemberId(generateMemberId(owner));
216	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
217	        owner.setHouseholdSize(countHouseholdSize(owner.getHouseholdId()));
218	        owner.setMembershipLevel(computeMembershipLevel(owner));
219	        owner.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
220	        owner.setCapacityWarning(isCityApproachingCapacity(owner.getCity()));
221	        this.clinicService.saveOwner(owner);
222	        if (idempotencyKey != null) {
223	            IDEMPOTENT_CREATES.put(idempotencyKey, owner.getId());
224	        }
225	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
226	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
227	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
228	        emitOwnerCreatedEvent(owner, ownerDto);
229	        enqueueWelcomeNotification(owner);
230	        headers.setLocation(UriComponentsBuilder.newInstance()
231	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
232	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
233	    }
