330	    /**
331	     * Emits an immutable structured {@code OWNER_CREATED} event to the {@code AUDIT} logger, alongside the
332	     * human-readable audit line. The event is a JSON object
333	     * {@code {seq, ownerId, memberId, membershipLevel, event}} where {@code seq} is a process-wide,
334	     * monotonically increasing sequence number across all creates.
335	     *
336	     * <p>The {@code memberId} field carries the owner's <em>current primary identifier</em> — see
337	     * {@link #primaryIdentifier(Owner)} — which is now the unified member id.
338	     *
339	     * @param owner    the freshly persisted owner
340	     * @param ownerDto its DTO projection, used for the derived membership level
341	     */
342	    private void emitOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
343	        Map<String, Object> event = new LinkedHashMap<>();
344	        event.put("seq", OWNER_CREATED_SEQUENCE.incrementAndGet());
345	        event.put("ownerId", owner.getId());
346	        event.put("memberId", primaryIdentifier(owner));
347	        event.put("membershipLevel", ownerDto.getMembershipLevel());
348	        event.put("event", "OWNER_CREATED");
349	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
350	    }
351	
352	    /**
353	     * Enqueues a welcome notification for a freshly created owner by emitting a line to the {@code NOTIFY}
354	     * logger carrying the owner id and the assigned member id. Downstream notification delivery consumes
355	     * this signal; capturing the logger lets the side-effect be asserted without an implementation hook.
356	     *
357	     * @param owner the freshly persisted owner
358	     */
359	    private void enqueueWelcomeNotification(Owner owner) {
360	        NOTIFY.info("welcome notification enqueued ownerId={} memberId={}",
361	            owner.getId(), owner.getMemberId());
362	    }
363	
364	    /**
365	     * Returns the owner's current primary identifier, which structured audit events must carry. This is the
366	     * single point that decides which field is primary: the unified {@code memberId}.
367	     *
368	     * @param owner the owner whose primary identifier is required
369	     * @return the current primary identifier
370	     */
371	    private String primaryIdentifier(Owner owner) {
372	        return owner.getMemberId();
373	    }
374	
375	    /**
376	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
377	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
378	     *
379	     * @param fields the submitted owner fields
380	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
381	     *                                        {@code null} or blank, or if the owner supplies no address
382	     *                                        in either form (a blank structured {@code addressLine1} and a
383	     *                                        blank flat {@code address}, each measured after normalization)
384	     */
385	    /**
386	     * Reads the client-supplied {@code Idempotency-Key} header for the current create request, if any.
387	     *
388	     * @return the trimmed idempotency key, or {@code null} when the header is absent or blank
389	     */
390	    private String idempotencyKey() {
391	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
392	        if (key == null || key.isBlank()) {
393	            return null;
394	        }
395	        return key.strip();
396	    }
397	
398	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
399	        List<String> missing = new ArrayList<>();
400	        if (isBlank(fields.getFirstName())) {
401	            missing.add("firstName");
402	        }
403	        if (isBlank(fields.getLastName())) {
404	            missing.add("lastName");
405	        }
406	        boolean hasStructuredAddress = !isBlank(normalizeAddress(fields.getAddressLine1()));
407	        boolean hasFlatAddress = !isBlank(normalizeAddress(fields.getAddress()));
408	        if (!hasStructuredAddress && !hasFlatAddress) {
409	            missing.add("address");
410	        }
411	        if (isBlank(fields.getCity())) {
412	            missing.add("city");
413	        }
414	        if (isBlank(fields.getTelephone())) {
415	            missing.add("telephone");
416	        }
417	        if (!missing.isEmpty()) {
418	            throw new RequiredFieldsMissingException(missing);
419	        }
420	    }
421	
422	    private boolean isBlank(String value) {
423	        return value == null || value.isBlank();
424	    }
425	
426	    /**
427	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
428	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
429	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
430	     */
431	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
432	        "NSW", new int[] {2000, 2099},
433	        "VIC", new int[] {3000, 3099},
434	        "QLD", new int[] {4000, 4099});
435	
436	    /**
437	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
438	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
439	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
440	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
441	     *
442	     * @param postcode the submitted postcode, or {@code null} when omitted
443	     * @param city the owner's city, used to derive the region whose range constrains the postcode
444	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
445	     *                                  city's region
446	     */
447	    private void validatePostcode(String postcode, String city) {
448	        if (postcode == null) {
449	            return;
450	        }
451	        if (!postcode.matches("[0-9]{4}")) {
452	            throw new InvalidPostcodeException(postcode);
453	        }
454	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
455	        if (range == null) {
456	            return;
457	        }
458	        int value = Integer.parseInt(postcode);
459	        if (value < range[0] || value > range[1]) {
460	            throw new InvalidPostcodeException(postcode);
461	        }
462	    }
