542	            if (!isBlank(owner.getAddressLine2())) {
543	                String line2 = normalizeAddress(owner.getAddressLine2());
544	                owner.setAddressLine2(line2);
545	                composed = line1 + " " + line2;
546	            } else {
547	                owner.setAddressLine2(null);
548	            }
549	            owner.setAddress(composed);
550	        } else {
551	            owner.setAddressLine1(null);
552	            owner.setAddressLine2(null);
553	            owner.setAddress(normalizeAddress(owner.getAddress()));
